# Storyboard long_39 "What If You Could Grab Any Object On Earth?"
# The bag sits on a table; Rio reaches his arm into it (pose reach + item grabbag reach track); what comes out pops above the bag.
from sb import *
def door(x, **kw): d = {"k": "housedoor", "x": x}; d.update(kw); return d
APT = dict(wall="#c8c0a8", wall2="#7a7060", room={"frames": 260, "window": 1250})
TBL = {"k": "table", "x": 0.55, "w": 1.0}
def bag(reach=0, out=None, at=0, x=0.55): d = {"k": "grabbag", "x": x, "reach": reach}; d.update({"out": out, "at": at} if out else {}); return d
def grab(x=0.45, t0=0.1, t1=0.6, expr="determined", **kw):   # Rio's arm goes into the bag between t0 and t1
    return A("rio", x, [[0, "relaxed"], [t0, "reach"], [t1, "holdFront"]], expr, **kw)
def leo(x=0.75, pose="relaxed", expr="neutral", **kw): kw.setdefault("facing", -1); return A("leo2", x, pose, expr, **kw)

